content.content:
1	/* =========================================================
2	   AK - Event Discovery Website
3	   Simple HTML, CSS and JavaScript project
4	   ========================================================= */
5	
6	:root {
7	  --primary: #6c5ce7;
8	  --dark: #222222;
9	  --text: #333333;
10	  --muted: #666666;
11	  --bg: #f5f5f5;
12	  --white: #ffffff;
13	  --border: #dddddd;
14	}
15	
16	* {
17	  margin: 0;
18	  padding: 0;
19	  box-sizing: border-box;
20	}
21	
22	html {
23	  scroll-behavior: smooth;
24	  scroll-padding-top: 75px;
25	}
26	
27	body {
28	  font-family: "Poppins", Arial, sans-serif;
29	  background: var(--bg);
30	  color: var(--text);
31	  line-height: 1.5;
32	}
33	
34	img {
35	  display: block;
36	  max-width: 100%;
37	}
38	
39	a {
40	  text-decoration: none;
41	  color: inherit;
42	}
43	
44	ul {
45	  list-style: none;
46	}
47	
48	button,
49	input,
50	select {
51	  font-family: inherit;
52	}
53	
54	button {
55	  cursor: pointer;
56	  border: none;
57	  background: none;
58	}
59	
60	[hidden] {
61	  display: none !important;
62	}
63	
64	:focus-visible {
65	  outline: 2px solid var(--primary);
66	  outline-offset: 2px;
67	}
68	
69	.container {
70	  width: 100%;
71	  max-width: 1100px;
72	  margin: 0 auto;
73	  padding: 0 20px;
74	}
75	
76	/* ================= BUTTONS ================= */
77	.btn {
78	  display: inline-block;
79	  background: var(--primary);
80	  color: var(--white);
81	  padding: 9px 18px;
82	  border-radius: 5px;
83	  font-size: 14px;
84	}
85	
86	.btn:hover {
87	  background: #5a4bd1;
88	}
89	
90	.btn-outline {
91	  background: transparent;
92	  color: var(--primary);
93	  border: 1px solid var(--primary);
94	}
95	
96	.btn-outline:hover {
97	  background: var(--primary);
98	  color: var(--white);
99	}
100	
101	.btn-small {
102	  padding: 6px 12px;
103	  font-size: 13px;
104	}
105	
106	/* ================= HEADER ================= */
107	.header {
108	  position: sticky;
109	  top: 0;
110	  z-index: 50;
111	  background: var(--white);
112	  border-bottom: 1px solid var(--border);
113	}
114	
115	.nav {
116	  height: 65px;
117	  display: flex;
118	  align-items: center;
119	  justify-content: space-between;
120	  position: relative;
121	}
122	
123	.logo {
124	  display: inline-flex;
125	  align-items: center;
126	  line-height: 0;
127	}
128	
129	.logo-icon {
130	  display: block;
131	  width: 36px;
132	  height: 36px;
133	}
134	
135	.nav-menu {
136	  display: flex;
137	  align-items: center;
138	  gap: 30px;
139	}
140	
141	.nav-links {
142	  display: flex;
143	  align-items: center;
144	  gap: 24px;
145	}
146	
147	.nav-links a {
148	  font-size: 15px;
149	  color: #444444;
150	}
151	
152	.nav-links a:hover {
153	  color: var(--primary);
154	}
155	
156	.nav-buttons {
157	  display: flex;
158	  align-items: center;
159	  gap: 8px;
160	}
161	
162	.menu-btn {
163	  display: none;
164	  font-size: 24px;
165	  color: var(--dark);
166	  line-height: 1;
167	}
168	
169	/* ================= HERO ================= */
170	.hero {
171	  padding: 55px 0;
172	  background: #f0ecff;
173	}
174	
175	.hero-content {
176	  display: grid;
177	  grid-template-columns: 1.1fr 0.9fr;
178	  align-items: center;
179	  gap: 40px;
180	}
181	
182	.hero-tag {
183	  display: inline-block;
184	  margin-bottom: 14px;
185	  padding: 5px 12px;
186	  border: 1px solid #d5cdfa;
187	  border-radius: 20px;
188	  background: var(--white);
189	  color: var(--primary);
190	  font-size: 13px;
191	}
192	
193	.hero h1 {
194	  margin-bottom: 14px;
195	  font-size: 38px;
196	  line-height: 1.25;
197	  color: var(--dark);
198	}
199	
200	.hero h1 span {
201	  color: var(--primary);
202	}
203	
204	.hero-text > p {
205	  max-width: 520px;
206	  margin-bottom: 22px;
207	  color: var(--muted);
208	  font-size: 15px;
209	}
210	
211	.search-box {
212	  display: flex;
213	  gap: 8px;
214	  padding: 10px;
215	  border: 1px solid var(--border);
216	  border-radius: 6px;
217	  background: var(--white);
218	}
219	
220	.search-box input {
221	  flex: 1;
222	  min-width: 0;
223	  padding: 9px 12px;
224	  border: 1px solid #cccccc;
225	  border-radius: 4px;
226	  font-size: 14px;
227	  color: var(--text);
228	}
229	
230	.search-box input::placeholder {
231	  color: #999999;
232	}
233	
234	.search-box input:focus {
235	  border-color: var(--primary);
236	  outline: none;
237	}
238	
239	.search-box .btn {
240	  white-space: nowrap;
241	}
242	
243	.hero-stats {
244	  display: flex;
245	  gap: 35px;
246	  margin-top: 24px;
247	}
248	
249	.hero-stats strong {
250	  display: block;
251	  font-size: 22px;
252	  color: var(--dark);
253	  line-height: 1.3;
254	}
255	
256	.hero-stats span {
257	  font-size: 13px;
258	  color: var(--muted);
259	}
260	
261	.hero-image img {
262	  width: 100%;
263	  height: 340px;
264	  object-fit: cover;
265	  border-radius: 8px;
266	}
267	
268	/* ================= SECTIONS ================= */
269	.section {
270	  padding: 55px 0;
271	}
272	
273	.section-head {
274	  margin-bottom: 28px;
275	  text-align: center;
276	}
277	
278	.section-head h2 {
279	  margin-bottom: 6px;
280	  font-size: 26px;
281	  color: var(--dark);
282	  line-height: 1.3;
283	}
284	
285	.section-head p {
286	  color: var(--muted);
287	  font-size: 14px;
288	}
289	
290	/* ================= FILTERS ================= */
291	.filters {
292	  display: flex;
293	  flex-wrap: wrap;
294	  justify-content: center;
295	  gap: 8px;
296	  margin-bottom: 25px;
297	}
298	
299	.filter-btn {
300	  padding: 7px 16px;
301	  border: 1px solid var(--border);
302	  border-radius: 20px;
303	  background: var(--white);
304	  color: #555555;
305	  font-size: 14px;
306	}
307	
308	.filter-btn:hover {
309	  border-color: var(--primary);
310	  color: var(--primary);
311	}
312	
313	.filter-btn.active {
314	  background: var(--primary);
315	  border-color: var(--primary);
316	  color: var(--white);
317	}
318	
319	.saved-btn.active {
320	  background: #e74c3c;
321	  border-color: #e74c3c;
322	}
323	
324	/* ================= EVENT CARDS ================= */
325	.events-grid,
326	.trending-grid {
327	  display: grid;
328	  grid-template-columns: repeat(3, 1fr);
329	  gap: 20px;
330	}
331	
332	.event-card {
333	  display: flex;
334	  flex-direction: column;
335	  overflow: hidden;
336	  border: 1px solid var(--border);
337	  border-radius: 8px;
338	  background: var(--white);
339	}
340	
341	.event-card:hover {
342	  border-color: var(--primary);
343	}
344	
345	.card-image {
346	  position: relative;
347	}
348	
349	.card-image img {
350	  width: 100%;
351	  height: 175px;
352	  object-fit: cover;
353	}
354	
355	.category-badge {
356	  position: absolute;
357	  top: 10px;
358	  left: 10px;
359	  padding: 3px 9px;
360	  border: 1px solid #d5cdfa;
361	  border-radius: 4px;
362	  background: var(--white);
363	  color: var(--primary);
364	  font-size: 12px;
365	}
366	
367	.fav-btn {
368	  position: absolute;
369	  top: 10px;
370	  right: 10px;
371	  width: 32px;
372	  height: 32px;
373	  border: 1px solid var(--border);
374	  border-radius: 50%;
375	  background: var(--white);
376	  color: #999999;
377	  font-size: 16px;
378	}
379	
380	.fav-btn.active {
381	  color: #e74c3c;
382	}
383	
384	.card-body {
385	  display: flex;
386	  flex-direction: column;
387	  flex: 1;
388	  padding: 15px;
389	}
390	
391	.card-body h3 {
392	  margin-bottom: 6px;
393	  font-size: 17px;
394	  line-height: 1.4;
395	  color: var(--dark);
396	}
397	
398	.meta {
399	  margin-bottom: 4px;
400	  color: var(--muted);
401	  font-size: 13px;
402	}
403	
404	.card-footer {
405	  display: flex;
406	  align-items: center;
407	  justify-content: space-between;
408	  gap: 10px;
409	  margin-top: auto;
410	  padding-top: 12px;
411	  border-top: 1px solid #eeeeee;
412	}
413	
414	.card-body .card-footer {
415	  margin-top: 12px;
416	}
417	
418	.price {
419	  color: var(--primary);
420	  font-size: 15px;
421	  font-weight: 600;
422	}
423	
424	.no-results {
425	  padding: 30px;
426	  border: 1px solid var(--border);
427	  border-radius: 8px;
428	  background: var(--white);
429	  text-align: center;
430	}
431	
432	.no-results p {
433	  margin-bottom: 12px;
434	  color: var(--muted);
435	}
436	
437	/* ================= CATEGORIES ================= */
438	.categories {
439	  background: var(--white);
440	}
441	
442	.category-grid {
443	  display: grid;
444	  grid-template-columns: repeat(3, 1fr);
445	  gap: 16px;
446	}
447	
448	.category-card {
449	  width: 100%;
450	  padding: 22px 16px;
451	  border: 1px solid var(--border);
452	  border-radius: 8px;
453	  background: var(--white);
454	  text-align: center;
455	  color: var(--text);
456	}
457	
458	.category-card:hover {
459	  background: #f5f3ff;
460	  border-color: var(--primary);
461	}
462	
463	.cat-icon {
464	  display: block;
465	  margin-bottom: 8px;
466	  font-size: 30px;
467	  line-height: 1;
468	}
469	
470	.category-card h3 {
471	  margin-bottom: 3px;
472	  font-size: 16px;
473	  color: var(--dark);
474	}
475	
476	.category-card p {
477	  color: var(--muted);
478	  font-size: 13px;
479	}
480	
481	/* ================= TRENDING ================= */
482	.trending {
483	  background: var(--bg);
484	}
485	
486	.trend-card {
487	  display: flex;
488	  flex-direction: column;
489	  overflow: hidden;
490	  border: 1px solid var(--border);
491	  border-radius: 8px;
492	  background: var(--white);
493	}
494	
495	.trend-image {
496	  position: relative;
497	}
498	
499	.trend-image img {
500	  width: 100%;
501	  height: 165px;
502	  object-fit: cover;
503	}
504	
505	.rank-badge {
506	  position: absolute;
507	  top: 10px;
508	  left: 10px;
509	  padding: 3px 9px;
510	  border-radius: 4px;
511	  background: #ff9f43;
512	  color: var(--white);
513	  font-size: 12px;
514	}
515	
516	.trend-body {
517	  display: flex;
518	  flex-direction: column;
519	  flex: 1;
520	  padding: 15px;
521	}
522	
523	.trend-category {
524	  margin-bottom: 4px;
525	  color: #e67e22;
526	  font-size: 12px;
527	}
528	
529	.trend-body h3 {
530	  margin-bottom: 6px;
531	  color: var(--dark);
532	  font-size: 17px;
533	  line-height: 1.4;
534	}
535	
536	.trend-body .meta {
537	  color: var(--muted);
538	}
539	
540	.trend-body .price {
541	  color: var(--primary);
542	}
543	
544	.trend-body .card-footer {
545	  margin-top: 12px;
546	  border-top: 1px solid #eeeeee;
547	}
548	
549	/* ================= ABOUT ================= */
550	.about {
551	  display: grid;
552	  grid-template-columns: 1fr 1fr;
553	  align-items: center;
554	  gap: 40px;
555	}
556	
557	.about img {
558	  width: 100%;
559	  height: 320px;
560	  object-fit: cover;
561	  border-radius: 8px;
562	}
563	
564	.about-text h2 {
565	  margin-bottom: 12px;
566	  font-size: 26px;
567	  color: var(--dark);
568	  line-height: 1.3;
569	}
570	
571	.about-text p {
572	  margin-bottom: 10px;
573	  color: var(--muted);
574	  font-size: 15px;
575	}
576	
577	.about-list {
578	  margin-top: 15px;
579	}
580	
581	.about-list li {
582	  margin-bottom: 6px;
583	  color: #444444;
584	  font-size: 14px;
585	}
586	
587	/* ================= NEWSLETTER ================= */
588	.newsletter {
589	  padding: 50px 0;
590	  background: var(--primary);
591	  text-align: center;
592	  color: var(--white);
593	}
594	
595	.newsletter h2 {
596	  margin-bottom: 8px;
597	  font-size: 26px;
598	  line-height: 1.3;
599	}
600	
601	.newsletter p {
602	  margin-bottom: 20px;
603	  color: #eeebff;
604	  font-size: 14px;
605	}
606	
607	.newsletter form {
608	  display: flex;
609	  gap: 8px;
610	  max-width: 460px;
611	  margin: 0 auto;
612	}
613	
614	.newsletter input {
615	  flex: 1;
616	  min-width: 0;
617	  padding: 10px 14px;
618	  border: none;
619	  border-radius: 4px;
620	  font-size: 14px;
621	  color: var(--text);
622	}
623	
624	.newsletter input:focus {
625	  outline: 2px solid var(--white);
626	  outline-offset: 2px;
627	}
628	
629	.newsletter .btn {
630	  background: var(--dark);
631	  color: var(--white);
632	  white-space: nowrap;
633	}
634	
635	.newsletter .btn:hover {
636	  background: #000000;
637	}
638	
639	.form-msg {
640	  min-height: 20px;
641	  margin: 10px 0 0;
642	  font-size: 14px;
643	}
644	
645	.form-msg.error {
646	  color: #ffd6d6;
647	}
648	
649	.form-msg.success {
650	  color: #d9ffb8;
651	}
652	
653	.newsletter .form-msg {
654	  margin-bottom: 0;
655	}
656	
657	/* ================= FOOTER ================= */
658	.footer {
659	  padding-top: 45px;
660	  background: #333333;
661	  color: #dddddd;
662	}
663	
664	.footer-grid {
665	  display: grid;
666	  grid-template-columns: 1.5fr 1fr 1fr 1.2fr;
667	  gap: 30px;
668	  padding-bottom: 35px;
669	}
670	
671	.footer .logo {
672	  display: inline-flex;
673	  margin-bottom: 12px;
674	}
675	
676	.footer .logo-icon {
677	  width: 32px;
678	  height: 32px;
679	}
680	
681	.footer p {
682	  font-size: 14px;
683	  line-height: 1.7;
684	}
685	
686	.socials {
687	  display: flex;
688	  flex-wrap: wrap;
689	  gap: 12px;
690	  margin-top: 14px;
691	}
692	
693	.socials p {
694	  font-size: 14px;
695	  color: #cccccc;
696	}
697	
698	.footer h3 {
699	  margin-bottom: 12px;
700	  color: var(--white);
701	  font-size: 16px;
702	}
703	
704	.footer-links li {
705	  margin-bottom: 7px;
706	}
707	
708	.footer-links a {
709	  font-size: 14px;
710	  color: #cccccc;
711	}
712	
713	.footer-links a:hover,
714	.socials p:hover {
715	  color: var(--white);
716	}
717	
718	.footer-bottom {
719	  padding: 18px;
720	  border-top: 1px solid #555555;
721	  text-align: center;
722	  font-size: 13px;
723	}
724	
725	/* ================= MODAL ================= */
726	.modal {
727	  position: fixed;
728	  inset: 0;
729	  z-index: 100;
730	  display: none;
731	  padding: 20px;
732	  overflow-y: auto;
733	  background: rgba(0, 0, 0, 0.5);
734	}
735	
736	.modal.open {
737	  display: block;
738	}
739	
740	.modal-box {
741	  position: relative;
742	  width: 100%;
743	  max-width: 650px;
744	  margin: 30px auto;
745	  overflow: hidden;
746	  border-radius: 8px;
747	  background: var(--white);
748	}
749	
750	.modal-box img {
751	  width: 100%;
752	  height: 220px;
753	  object-fit: cover;
754	}
755	
756	.modal-close {
757	  position: absolute;
758	  top: 10px;
759	  right: 10px;
760	  width: 32px;
761	  height: 32px;
762	  border: 1px solid var(--border);
763	  border-radius: 50%;
764	  background: var(--white);
765	  color: var(--dark);
766	  font-size: 14px;
767	}
768	
769	.modal-body {
770	  padding: 20px;
771	}
772	
773	.modal-badge {
774	  position: static;
775	  display: inline-block;
776	  margin-bottom: 8px;
777	}
778	
779	.modal-body h2 {
780	  margin-bottom: 8px;
781	  color: var(--dark);
782	  font-size: 22px;
783	  line-height: 1.3;
784	}
785	
786	.modal-body > p {
787	  margin-bottom: 12px;
788	  color: var(--muted);
789	  font-size: 14px;
790	}
791	
792	.modal-info {
793	  margin-bottom: 18px;
794	}
795	
796	.modal-info li {
797	  margin-bottom: 5px;
798	  color: #444444;
799	  font-size: 14px;
800	}
801	
802	.modal-info strong {
803	  color: var(--dark);
804	}
805	
806	/* ================= FORMS ================= */
807	.back-btn {
808	  margin-bottom: 12px;
809	  color: var(--primary);
810	  font-size: 14px;
811	}
812	
813	.back-btn:hover {
814	  text-decoration: underline;
815	}
816	
817	.reg-event-info {
818	  margin-bottom: 15px;
819	  color: var(--muted);
820	  font-size: 14px;
821	}
822	
823	#registerTitle span {
824	  color: var(--primary);
825	}
826	
827	.form-group {
828	  margin-bottom: 10px;
829	}
830	
831	.form-group label {
832	  display: block;
833	  margin-bottom: 4px;
834	  color: var(--dark);
835	  font-size: 13px;
836	}
837	
838	.form-group input,
839	.form-group select {
840	  width: 100%;
841	  padding: 9px 11px;
842	  border: 1px solid #cccccc;
843	  border-radius: 4px;
844	  background: var(--white);
845	  color: var(--text);
846	  font-size: 14px;
847	}
848	
849	.form-group input:focus,
850	.form-group select:focus {
851	  border-color: var(--primary);
852	  outline: none;
853	}
854	
855	.form-group .input-error {
856	  border-color: #e74c3c;
857	}
858	
859	.field-error {
860	  display: block;
861	  min-height: 15px;
862	  margin-top: 2px;
863	  color: #e74c3c;
864	  font-size: 12px;
865	}
866	
867	.btn-full {
868	  width: 100%;
869	  margin-top: 4px;
870	}
871	
872	.register-success {
873	  padding: 18px;
874	  border: 1px solid #b7e4c7;
875	  border-radius: 6px;
876	  background: #eafaf0;
877	  text-align: center;
878	}
879	
880	.register-success p {
881	  margin-bottom: 7px;
882	  color: #1e6b3a;
883	  font-size: 14px;
884	}
885	
886	.register-success .reg-success-note {
887	  color: #3d7a55;
888	  font-size: 13px;
889	}
890	
891	.register-success .btn {
892	  margin-top: 6px;
893	}
894	
895	/* ================= LOGIN / SIGNUP ================= */
896	.auth-box {
897	  max-width: 420px;
898	  margin-top: 50px;
