/* =========================================================
   AK - Event Discovery Website
   Simple HTML, CSS and JavaScript project
   ========================================================= */

:root {
  --primary: #6c5ce7;
  --dark: #222222;
  --text: #333333;
  --muted: #666666;
  --bg: #f5f5f5;
  --white: #ffffff;
  --border: #dddddd;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 75px;
}

body {
  font-family: "Poppins", Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

img {
  display: block;
  max-width: 100%;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

button,
input,
select {
  font-family: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.container {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 20px;
}

/* ================= BUTTONS ================= */
.btn {
  display: inline-block;
  background: var(--primary);
  color: var(--white);
  padding: 9px 18px;
  border-radius: 5px;
  font-size: 14px;
}

.btn:hover {
  background: #5a4bd1;
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 1px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary);
  color: var(--white);
}

.btn-small {
  padding: 6px 12px;
  font-size: 13px;
}

/* ================= HEADER ================= */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--white);
  border-bottom: 1px solid var(--border);
}

.nav {
  height: 65px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}

.logo {
  display: inline-flex;
  align-items: center;
  line-height: 0;
}

.logo-icon {
  display: block;
  width: 36px;
  height: 36px;
}

.nav-menu {
  display: flex;
  align-items: center;
  gap: 30px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 24px;
}

.nav-links a {
  font-size: 15px;
  color: #444444;
}

.nav-links a:hover {
  color: var(--primary);
}

.nav-buttons {
  display: flex;
  align-items: center;
  gap: 8px;
}

.menu-btn {
  display: none;
  font-size: 24px;
  color: var(--dark);
  line-height: 1;
}

/* ================= HERO ================= */
.hero {
  padding: 55px 0;
  background: #f0ecff;
}

.hero-content {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  gap: 40px;
}

.hero-tag {
  display: inline-block;
  margin-bottom: 14px;
  padding: 5px 12px;
  border: 1px solid #d5cdfa;
  border-radius: 20px;
  background: var(--white);
  color: var(--primary);
  font-size: 13px;
}

.hero h1 {
  margin-bottom: 14px;
  font-size: 38px;
  line-height: 1.25;
  color: var(--dark);
}

.hero h1 span {
  color: var(--primary);
}

.hero-text > p {
  max-width: 520px;
  margin-bottom: 22px;
  color: var(--muted);
  font-size: 15px;
}

.search-box {
  display: flex;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--white);
}

.search-box input {
  flex: 1;
  min-width: 0;
  padding: 9px 12px;
  border: 1px solid #cccccc;
  border-radius: 4px;
  font-size: 14px;
  color: var(--text);
}

.search-box input::placeholder {
  color: #999999;
}

.search-box input:focus {
  border-color: var(--primary);
  outline: none;
}

.search-box .btn {
  white-space: nowrap;
}

.hero-stats {
  display: flex;
  gap: 35px;
  margin-top: 24px;
}

.hero-stats strong {
  display: block;
  font-size: 22px;
  color: var(--dark);
  line-height: 1.3;
}

.hero-stats span {
  font-size: 13px;
  color: var(--muted);
}

.hero-image img {
  width: 100%;
  height: 340px;
  object-fit: cover;
  border-radius: 8px;
}

/* ================= SECTIONS ================= */
.section {
  padding: 55px 0;
}

.section-head {
  margin-bottom: 28px;
  text-align: center;
}

.section-head h2 {
  margin-bottom: 6px;
  font-size: 26px;
  color: var(--dark);
  line-height: 1.3;
}

.section-head p {
  color: var(--muted);
  font-size: 14px;
}

/* ================= FILTERS ================= */
.filters {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-bottom: 25px;
}

.filter-btn {
  padding: 7px 16px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--white);
  color: #555555;
  font-size: 14px;
}

.filter-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.filter-btn.active {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--white);
}

.saved-btn.active {
  background: #e74c3c;
  border-color: #e74c3c;
}

/* ================= EVENT CARDS ================= */
.events-grid,
.trending-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.event-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--white);
}

.event-card:hover {
  border-color: var(--primary);
}

.card-image {
  position: relative;
}

.card-image img {
  width: 100%;
  height: 175px;
  object-fit: cover;
}

.category-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  padding: 3px 9px;
  border: 1px solid #d5cdfa;
  border-radius: 4px;
  background: var(--white);
  color: var(--primary);
  font-size: 12px;
}

.fav-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 32px;
  height: 32px;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--white);
  color: #999999;
  font-size: 16px;
}

.fav-btn.active {
  color: #e74c3c;
}

.card-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 15px;
}

.card-body h3 {
  margin-bottom: 6px;
  font-size: 17px;
  line-height: 1.4;
  color: var(--dark);
}

.meta {
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 13px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid #eeeeee;
}

.card-body .card-footer {
  margin-top: 12px;
}

.price {
  color: var(--primary);
  font-size: 15px;
  font-weight: 600;
}

.no-results {
  padding: 30px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--white);
  text-align: center;
}

.no-results p {
  margin-bottom: 12px;
  color: var(--muted);
}

/* ================= CATEGORIES ================= */
.categories {
  background: var(--white);
}

.category-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.category-card {
  width: 100%;
  padding: 22px 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--white);
  text-align: center;
  color: var(--text);
}

.category-card:hover {
  background: #f5f3ff;
  border-color: var(--primary);
}

.cat-icon {
  display: block;
  margin-bottom: 8px;
  font-size: 30px;
  line-height: 1;
}

.category-card h3 {
  margin-bottom: 3px;
  font-size: 16px;
  color: var(--dark);
}

.category-card p {
  color: var(--muted);
  font-size: 13px;
}

/* ================= TRENDING ================= */
.trending {
  background: var(--bg);
}

.trend-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--white);
}

.trend-image {
  position: relative;
}

.trend-image img {
  width: 100%;
  height: 165px;
  object-fit: cover;
}

.rank-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  padding: 3px 9px;
  border-radius: 4px;
  background: #ff9f43;
  color: var(--white);
  font-size: 12px;
}

.trend-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 15px;
}

.trend-category {
  margin-bottom: 4px;
  color: #e67e22;
  font-size: 12px;
}

.trend-body h3 {
  margin-bottom: 6px;
  color: var(--dark);
  font-size: 17px;
  line-height: 1.4;
}

.trend-body .meta {
  color: var(--muted);
}

.trend-body .price {
  color: var(--primary);
}

.trend-body .card-footer {
  margin-top: 12px;
  border-top: 1px solid #eeeeee;
}

/* ================= ABOUT ================= */
.about {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 40px;
}

.about img {
  width: 100%;
  height: 320px;
  object-fit: cover;
  border-radius: 8px;
}

.about-text h2 {
  margin-bottom: 12px;
  font-size: 26px;
  color: var(--dark);
  line-height: 1.3;
}

.about-text p {
  margin-bottom: 10px;
  color: var(--muted);
  font-size: 15px;
}

.about-list {
  margin-top: 15px;
}

.about-list li {
  margin-bottom: 6px;
  color: #444444;
  font-size: 14px;
}

/* ================= NEWSLETTER ================= */
.newsletter {
  padding: 50px 0;
  background: var(--primary);
  text-align: center;
  color: var(--white);
}

.newsletter h2 {
  margin-bottom: 8px;
  font-size: 26px;
  line-height: 1.3;
}

.newsletter p {
  margin-bottom: 20px;
  color: #eeebff;
  font-size: 14px;
}

.newsletter form {
  display: flex;
  gap: 8px;
  max-width: 460px;
  margin: 0 auto;
}

.newsletter input {
  flex: 1;
  min-width: 0;
  padding: 10px 14px;
  border: none;
  border-radius: 4px;
  font-size: 14px;
  color: var(--text);
}

.newsletter input:focus {
  outline: 2px solid var(--white);
  outline-offset: 2px;
}

.newsletter .btn {
  background: var(--dark);
  color: var(--white);
  white-space: nowrap;
}

.newsletter .btn:hover {
  background: #000000;
}

.form-msg {
  min-height: 20px;
  margin: 10px 0 0;
  font-size: 14px;
}

.form-msg.error {
  color: #ffd6d6;
}

.form-msg.success {
  color: #d9ffb8;
}

.newsletter .form-msg {
  margin-bottom: 0;
}

/* ================= FOOTER ================= */
.footer {
  padding-top: 45px;
  background: #333333;
  color: #dddddd;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.2fr;
  gap: 30px;
  padding-bottom: 35px;
}

.footer .logo {
  display: inline-flex;
  margin-bottom: 12px;
}

.footer .logo-icon {
  width: 32px;
  height: 32px;
}

.footer p {
  font-size: 14px;
  line-height: 1.7;
}

.socials {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 14px;
}

.socials p {
  font-size: 14px;
  color: #cccccc;
}

.footer h3 {
  margin-bottom: 12px;
  color: var(--white);
  font-size: 16px;
}

.footer-links li {
  margin-bottom: 7px;
}

.footer-links a {
  font-size: 14px;
  color: #cccccc;
}

.footer-links a:hover,
.socials p:hover {
  color: var(--white);
}

.footer-bottom {
  padding: 18px;
  border-top: 1px solid #555555;
  text-align: center;
  font-size: 13px;
}

/* ================= MODAL ================= */
.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: none;
  padding: 20px;
  overflow-y: auto;
  background: rgba(0, 0, 0, 0.5);
}

.modal.open {
  display: block;
}

.modal-box {
  position: relative;
  width: 100%;
  max-width: 650px;
  margin: 30px auto;
  overflow: hidden;
  border-radius: 8px;
  background: var(--white);
}

.modal-box img {
  width: 100%;
  height: 220px;
  object-fit: cover;
}

.modal-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 32px;
  height: 32px;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--white);
  color: var(--dark);
  font-size: 14px;
}

.modal-body {
  padding: 20px;
}

.modal-badge {
  position: static;
  display: inline-block;
  margin-bottom: 8px;
}

.modal-body h2 {
  margin-bottom: 8px;
  color: var(--dark);
  font-size: 22px;
  line-height: 1.3;
}

.modal-body > p {
  margin-bottom: 12px;
  color: var(--muted);
  font-size: 14px;
}

.modal-info {
  margin-bottom: 18px;
}

.modal-info li {
  margin-bottom: 5px;
  color: #444444;
  font-size: 14px;
}

.modal-info strong {
  color: var(--dark);
}

/* ================= FORMS ================= */
.back-btn {
  margin-bottom: 12px;
  color: var(--primary);
  font-size: 14px;
}

.back-btn:hover {
  text-decoration: underline;
}

.reg-event-info {
  margin-bottom: 15px;
  color: var(--muted);
  font-size: 14px;
}

#registerTitle span {
  color: var(--primary);
}

.form-group {
  margin-bottom: 10px;
}

.form-group label {
  display: block;
  margin-bottom: 4px;
  color: var(--dark);
  font-size: 13px;
}

.form-group input,
.form-group select {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid #cccccc;
  border-radius: 4px;
  background: var(--white);
  color: var(--text);
  font-size: 14px;
}

.form-group input:focus,
.form-group select:focus {
  border-color: var(--primary);
  outline: none;
}

.form-group .input-error {
  border-color: #e74c3c;
}

.field-error {
  display: block;
  min-height: 15px;
  margin-top: 2px;
  color: #e74c3c;
  font-size: 12px;
}

.btn-full {
  width: 100%;
  margin-top: 4px;
}

.register-success {
  padding: 18px;
  border: 1px solid #b7e4c7;
  border-radius: 6px;
  background: #eafaf0;
  text-align: center;
}

.register-success p {
  margin-bottom: 7px;
  color: #1e6b3a;
  font-size: 14px;
}

.register-success .reg-success-note {
  color: #3d7a55;
  font-size: 13px;
}

.register-success .btn {
  margin-top: 6px;
}

/* ================= LOGIN / SIGNUP ================= */
.auth-box {
  max-width: 420px;
  margin-top: 50px;
}

.modal-box .auth-logo {
  width: 48px;
  height: 48px;
  margin: 0 auto 12px;
  object-fit: contain;
}

#loginPanel h2,
#signupPanel h2 {
  text-align: center;
}

.auth-subtitle {
  margin-bottom: 15px;
  color: var(--muted);
  font-size: 14px;
  text-align: center;
}

.auth-switch {
  margin-top: 14px;
  color: var(--muted);
  font-size: 13px;
  text-align: center;
}

.link-btn {
  color: var(--primary);
  font-size: inherit;
  text-decoration: underline;
}

/* ================= RESPONSIVE ================= */
@media (max-width: 992px) {
  .hero h1 {
    font-size: 34px;
  }

  .hero-content {
    gap: 28px;
  }

  .events-grid,
  .category-grid,
  .trending-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 900px) {
  .hero-content {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .hero-image img {
    height: 280px;
  }

  .hero-text > p {
    max-width: 100%;
  }
}

@media (max-width: 768px) {
  .menu-btn {
    display: block;
  }

  .nav-menu {
    position: absolute;
    top: 65px;
    left: 0;
    display: none;
    width: 100%;
    flex-direction: column;
    align-items: stretch;
    gap: 16px;
    padding: 18px;
    background: var(--white);
    border-bottom: 1px solid var(--border);
  }

  .nav-menu.open {
    display: flex;
  }

  .nav-links {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .nav-buttons {
    justify-content: flex-start;
  }

  .hero {
    padding: 40px 0;
  }

  .hero h1 {
    font-size: 30px;
  }

  .search-box {
    flex-direction: column;
  }

  .search-box .btn {
    width: 100%;
  }

  .hero-stats {
    gap: 22px;
  }

  .section {
    padding: 40px 0;
  }

  .section-head h2 {
    font-size: 24px;
  }

  .about {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .about img {
    height: 250px;
  }

  .newsletter form {
    flex-direction: column;
  }

  .newsletter .btn {
    width: 100%;
  }

  .trending-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    gap: 25px 18px;
  }
}

@media (max-width: 576px) {
  .hero h1 {
    font-size: 26px;
  }

  .hero-stats {
    justify-content: space-between;
    gap: 10px;
  }

  .hero-stats strong {
    font-size: 20px;
  }

  .events-grid {
    grid-template-columns: 1fr;
  }

  .category-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }

  .category-card {
    padding: 18px 12px;
  }

  .cat-icon {
    font-size: 26px;
  }

  .card-image img {
    height: 190px;
  }

  .filters {
    gap: 7px;
  }

  .filter-btn {
    padding: 6px 12px;
    font-size: 13px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 22px;
  }

  .modal {
    padding: 10px;
  }

  .modal-box {
    margin: 10px auto;
  }

  .modal-box img {
    height: 170px;
  }

  .modal-body {
    padding: 16px;
  }

  .newsletter h2 {
    font-size: 24px;
  }
}

@media (max-width: 400px) {
  .category-grid {
    grid-template-columns: 1fr;
  }

  .hero-stats {
    flex-wrap: wrap;
  }
}

