563	  signupForm.reset();
564	
565	  authFields.forEach(function (field) {
566	    setFieldError(field.input, field.error, "");
567	  });
568	}
569	
570	function showAuthPanel(mode) {
571	  loginPanel.hidden = mode !== "login";
572	  signupPanel.hidden = mode !== "signup";
573	  authSuccess.hidden = true;
574	  authModal.setAttribute("aria-labelledby", mode === "login" ? "authTitle" : "signupTitle");
575	
576	  authFields.forEach(function (field) {
577	    setFieldError(field.input, field.error, "");
578	  });
579	
580	  if (mode === "login") {
581	    loginEmail.focus();
582	  } else {
583	    signupName.focus();
584	  }
585	}
586	
587	function openAuthModal(mode) {
588	  resetAuthModal();
589	  authModal.classList.add("open");
590	  document.body.style.overflow = "hidden";
591	  navMenu.classList.remove("open");
592	  menuBtn.textContent = "☰";
593	  menuBtn.setAttribute("aria-expanded", "false");
594	  showAuthPanel(mode);
595	}
596	
597	function closeAuthModal() {
598	  authModal.classList.remove("open");
599	  document.body.style.overflow = modal.classList.contains("open") ? "hidden" : "";
600	  resetAuthModal();
601	}
602	
603	function showAuthSuccess(message) {
604	  loginPanel.hidden = true;
605	  signupPanel.hidden = true;
606	  authSuccessText.textContent = message;
607	  authSuccess.hidden = false;
608	  authDone.focus();
609	}
610	
611	// ---------- Event listeners ----------
612	searchForm.addEventListener("submit", function (event) {
613	  event.preventDefault();
614	
615	  searchTerm = searchInput.value.trim().toLowerCase();
616	  locationTerm = locationInput.value.trim().toLowerCase();
617	  showSaved = false;
618	
619	  renderEvents();
620	  document.getElementById("events").scrollIntoView({ behavior: "smooth" });
621	});
622	
623	document.querySelectorAll(".filter-btn[data-category]").forEach(function (button) {
624	  button.addEventListener("click", function () {
625	    currentCategory = button.dataset.category;
626	    showSaved = false;
627	    renderEvents();
628	  });
629	});
630	
631	document.querySelectorAll(".category-card").forEach(function (card) {
632	  card.addEventListener("click", function () {
633	    currentCategory = card.dataset.category;
634	    showSaved = false;
635	    searchTerm = "";
636	    locationTerm = "";
637	    searchInput.value = "";
638	    locationInput.value = "";
639	
640	    renderEvents();
641	    document.getElementById("events").scrollIntoView({ behavior: "smooth" });
642	  });
643	});
644	
645	savedBtn.addEventListener("click", function () {
646	  showSaved = !showSaved;
647	  renderEvents();
648	});
649	
650	clearFilters.addEventListener("click", function () {
651	  currentCategory = "all";
652	  searchTerm = "";
653	  locationTerm = "";
654	  showSaved = false;
655	  searchInput.value = "";
656	  locationInput.value = "";
657	
658	  renderEvents();
659	});
660	
661	document.addEventListener("click", function (event) {
662	  const favButton = event.target.closest("[data-fav]");
663	
664	  if (favButton) {
665	    toggleFavorite(favButton.dataset.fav);
666	    return;
667	  }
668	
669	  const detailsButton = event.target.closest("[data-details]");
670	
671	  if (detailsButton) {
672	    openModal(detailsButton.dataset.details);
673	  }
674	});
675	
676	modalClose.addEventListener("click", closeModal);
677	
678	modal.addEventListener("click", function (event) {
679	  if (event.target === modal) {
680	    closeModal();
681	  }
682	});
683	
684	document.addEventListener("keydown", function (event) {
685	  if (event.key !== "Escape") {
686	    return;
687	  }
688	
689	  if (modal.classList.contains("open")) {
690	    closeModal();
691	  }
692	
693	  if (authModal.classList.contains("open")) {
694	    closeAuthModal();
695	  }
696	});
697	
698	modalRegister.addEventListener("click", openRegisterPanel);
699	backToDetails.addEventListener("click", closeRegisterPanel);
700	registerDone.addEventListener("click", closeModal);
701	
702	registerFields.forEach(function (field) {
703	  field.input.addEventListener("input", function () {
704	    setFieldError(field.input, field.error, "");
705	  });
706	});
707	
708	registerForm.addEventListener("submit", function (event) {
709	  event.preventDefault();
710	
711	  const nameError = validateName(regName.value);
712	  const emailError = validateEmail(regEmail.value);
713	  const phoneError = validatePhone(regPhone.value);
714	  const ticketsError = validateTickets(regTickets.value);
715	
716	  setFieldError(regName, regNameError, nameError);
717	  setFieldError(regEmail, regEmailError, emailError);
718	  setFieldError(regPhone, regPhoneError, phoneError);
719	  setFieldError(regTickets, regTicketsError, ticketsError);
720	
721	  if (nameError || emailError || phoneError || ticketsError) {
722	    const firstInvalid = nameError
723	      ? regName
724	      : emailError
725	      ? regEmail
726	      : phoneError
727	      ? regPhone
728	      : regTickets;
729	
730	    firstInvalid.focus();
731	    return;
732	  }
733	
734	  const selectedEvent = allEvents.find(function (item) {
735	    return item.id === currentEventId;
736	  });
737	  const ticketCount = Number(regTickets.value);
738	  const ticketText = ticketCount === 1 ? "1 ticket" : ticketCount + " tickets";
739	
740	  successEvent.textContent = selectedEvent ? selectedEvent.title : "your event";
741	  successNote.textContent = ticketText + " · Confirmation sent to " + regEmail.value.trim();
742	
743	  registerForm.hidden = true;
744	  registerSuccess.hidden = false;
745	  registerDone.focus();
746	});
747	
748	// ---------- Newsletter ----------
749	newsletterForm.addEventListener("submit", function (event) {
750	  event.preventDefault();
751	
752	  const email = emailInput.value.trim();
753	  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
754	
755	  if (email === "") {
756	    newsletterMsg.textContent = "Please enter your email address.";
757	    newsletterMsg.className = "form-msg error";
758	    return;
759	  }
760	
761	  if (!emailPattern.test(email)) {
762	    newsletterMsg.textContent = "Please enter a valid email address.";
763	    newsletterMsg.className = "form-msg error";
764	    return;
765	  }
766	
767	  newsletterMsg.textContent = "Thank you for subscribing! Check your inbox for weekly events.";
768	  newsletterMsg.className = "form-msg success";
769	  newsletterForm.reset();
770	});
771	
772	emailInput.addEventListener("input", function () {
773	  newsletterMsg.textContent = "";
774	  newsletterMsg.className = "form-msg";
775	});
776	
777	// ---------- Mobile menu ----------
778	menuBtn.addEventListener("click", function () {
779	  const isOpen = navMenu.classList.toggle("open");
780	
781	  menuBtn.textContent = isOpen ? "✕" : "☰";
782	  menuBtn.setAttribute("aria-label", isOpen ? "Close menu" : "Open menu");
783	  menuBtn.setAttribute("aria-expanded", isOpen ? "true" : "false");
784	});
785	
786	navMenu.querySelectorAll("a").forEach(function (link) {
787	  link.addEventListener("click", function () {
788	    navMenu.classList.remove("open");
789	    menuBtn.textContent = "☰";
790	    menuBtn.setAttribute("aria-expanded", "false");
791	  });
792	});
793	
794	// ---------- Login / Signup ----------
795	loginBtn.addEventListener("click", function () {
796	  if (currentUser) {
797	    clearUser();
798	    return;
799	  }
800	
801	  openAuthModal("login");
802	});
803	
804	signupBtn.addEventListener("click", function () {
805	  openAuthModal("signup");
806	});
807	
808	authClose.addEventListener("click", closeAuthModal);
809	authDone.addEventListener("click", closeAuthModal);
810	
811	authModal.addEventListener("click", function (event) {
812	  if (event.target === authModal) {
813	    closeAuthModal();
814	  }
815	});
816	
817	showSignup.addEventListener("click", function () {
818	  showAuthPanel("signup");
819	});
820	
821	showLogin.addEventListener("click", function () {
822	  showAuthPanel("login");
823	});
824	
825	authFields.forEach(function (field) {
826	  field.input.addEventListener("input", function () {
827	    setFieldError(field.input, field.error, "");
828	  });
829	});
830	
831	loginForm.addEventListener("submit", function (event) {
832	  event.preventDefault();
833	
834	  const emailError = validateEmail(loginEmail.value);
835	  const passwordError = validatePassword(loginPassword.value);
836	
837	  setFieldError(loginEmail, loginEmailError, emailError);
838	  setFieldError(loginPassword, loginPasswordError, passwordError);
839	
840	  if (emailError) {
841	    loginEmail.focus();
842	    return;
843	  }
844	
845	  if (passwordError) {
846	    loginPassword.focus();
847	    return;
848	  }
849	
850	  const email = loginEmail.value.trim().toLowerCase();
851	  const name = currentUser && currentUser.email === email ? currentUser.name : email.split("@")[0];
852	
853	  saveUser({ name: name, email: email });
854	  showAuthSuccess("Logged in successfully. Welcome back, " + name + "!");
855	});
856	
857	signupForm.addEventListener("submit", function (event) {
858	  event.preventDefault();
859	
860	  const nameError = validateName(signupName.value);
861	  const emailError = validateEmail(signupEmail.value);
862	  const passwordError = validatePassword(signupPassword.value);
863	  const confirmError = validateConfirmPassword(signupConfirm.value);
864	
865	  setFieldError(signupName, signupNameError, nameError);
866	  setFieldError(signupEmail, signupEmailError, emailError);
867	  setFieldError(signupPassword, signupPasswordError, passwordError);
868	  setFieldError(signupConfirm, signupConfirmError, confirmError);
869	
870	  if (nameError) {
871	    signupName.focus();
872	    return;
873	  }
874	
875	  if (emailError) {
876	    signupEmail.focus();
877	    return;
878	  }
879	
880	  if (passwordError) {
881	    signupPassword.focus();
882	    return;
883	  }
884	
885	  if (confirmError) {
886	    signupConfirm.focus();
887	    return;
888	  }
889	
890	  const name = signupName.value.trim();
891	  const email = signupEmail.value.trim().toLowerCase();
892	
893	  saveUser({ name: name, email: email });
894	  showAuthSuccess("Account created. Welcome to AK, " + name + "!");
895	});
896	
897	// ---------- Start ----------
898	updateAuthUI();
899	renderEvents();
900	renderTrending();
901

