279	
280	    if (showSaved && !favorites.includes(event.id)) {
281	      return false;
282	    }
283	
284	    if (searchTerm) {
285	      const text = (
286	        event.title + " " + event.category + " " + event.venue + " " + event.location
287	      ).toLowerCase();
288	
289	      if (!text.includes(searchTerm)) {
290	        return false;
291	      }
292	    }
293	
294	    if (locationTerm) {
295	      const place = (event.location + " " + event.venue).toLowerCase();
296	
297	      if (!place.includes(locationTerm)) {
298	        return false;
299	      }
300	    }
301	
302	    return true;
