453	// ---------- Registration validation ----------
454	function validateName(value) {
455	  const name = value.trim();
456	
457	  if (name.length < 3 || !/^[A-Za-z ]+$/.test(name)) {
458	    return "Enter your full name using letters only.";
459	  }
460	
461	  return "";
462	}
463	
464	function validateEmail(value) {
465	  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
466	    return "Enter a valid email address.";
467	  }
468	
469	  return "";
470	}
471	
472	function validatePhone(value) {
473	  let digits = value.replace(/[\s\-()]/g, "");
474	
475	  if (digits.indexOf("+91") === 0) {
476	    digits = digits.slice(3);
477	  }
478	
479	  if (digits.indexOf("0") === 0) {
480	    digits = digits.slice(1);
481	  }
482	
483	  if (!/^[6-9][0-9]{9}$/.test(digits)) {
484	    return "Enter a valid 10-digit mobile number starting with 6-9.";
485	  }
486	
487	  return "";
488	}
489	
490	function validateTickets(value) {
491	  const count = Number(value);
492	
493	  if (!Number.isInteger(count) || count < 1 || count > 5) {
494	    return "Choose between 1 and 5 tickets.";
495	  }
496	
497	  return "";
498	}
