507	function validatePassword(value) {
508	  if (value.length < 6) {
509	    return "Password must be at least 6 characters.";
510	  }
511	
512	  return "";
513	}
514	
515	function validateConfirmPassword(value) {
516	  if (value === "") {
517	    return "Please confirm your password.";
518	  }
519	
520	  if (value !== signupPassword.value) {
521	    return "Passwords do not match.";
522	  }
523	
524	  return "";
525	}
